const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchRetry(url, { retries = 3, delay = 10 } = {}) {
    for (let attempt = 1; ; attempt++) {
        try {
            const response = await fetch(url);
            if (response.status < 500) return response;
            console.log(`urinish ${attempt}: HTTP ${response.status}`);
        } catch (error) {
            console.log(`urinish ${attempt}: ${error.message}`);
        }
        if (attempt > retries) throw new Error("urinishlar tugadi");
        await sleep(delay * 2 ** (attempt - 1));
    }
}

const response = await fetchRetry(url);
console.log(await response.text(), "- so'rovlar soni:", hits);
