import { createServer } from "node:http";

let hits = 0;
const server = createServer((req, res) => {
    hits++;
    setTimeout(() => res.end(JSON.stringify({ hits })), 30);
}).listen(0);
const url = `http://localhost:${server.address().port}/`;

const inFlight = new Map();
function fetchOnce(url) {
    if (!inFlight.has(url)) {
        const promise = fetch(url).then((response) => response.json()).finally(() => inFlight.delete(url));
        inFlight.set(url, promise);
    }
    return inFlight.get(url);
}

const results = await Promise.all([fetchOnce(url), fetchOnce(url), fetchOnce(url)]);
