const routes = [
    { pattern: "/", view: "HomePage" },
    { pattern: "/about", view: "AboutPage" },
    { pattern: "/users/:id", view: "UserPage" },
];

function matchRoute(pattern, path) {
    const names = [];
    const source = pattern.replace(/:([a-z]+)/gi, (_, name) => (names.push(name), "([^/]+)"));
    const match = new RegExp(`^${source}$`).exec(path);
    return match ? Object.fromEntries(names.map((name, i) => [name, match[i + 1]])) : null;
}

function resolve(href) {
    const { pathname, searchParams } = new URL(href, "https://app.local");
    for (const route of routes) {
        const params = matchRoute(route.pattern, pathname);
        if (params) return { view: route.view, params, query: Object.fromEntries(searchParams) };
    }
    return { view: "NotFound", params: {}, query: {} };
}

