class FakeObserver {
    #targets = new Set();
    constructor(callback) {
        this.callback = callback;
    }
    observe(target) {
        this.#targets.add(target);
    }
    unobserve(target) {
        this.#targets.delete(target);
    }
    disconnect() {
        this.#targets.clear();
    }
    trigger(changes) {
        const entries = changes.filter((change) => this.#targets.has(change.target));
        if (entries.length > 0) this.callback(entries, this);
    }
}

const a = { id: "a" };
const b = { id: "b" };
const observer = new FakeObserver((entries) => console.log("callback:", entries.map((entry) => entry.target.id)));

observer.observe(a);
