class ViewTracker {
    #since = new Map();
    #total = new Map();
    constructor(now) {
        this.now = now;
    }
    update(id, isVisible) {
        if (isVisible && !this.#since.has(id)) {
            this.#since.set(id, this.now());
        } else if (!isVisible && this.#since.has(id)) {
            const spent = this.now() - this.#since.get(id);
            this.#since.delete(id);
            this.#total.set(id, (this.#total.get(id) ?? 0) + spent);
        }
    }
    report() {
        return Object.fromEntries(this.#total);
    }
}

