function createRpc(port, handlers = {}) {
    let nextId = 0;
    const pending = new Map();
    port.onmessage = async ({ data }) => {
        if (data.method) {
            const result = await handlers[data.method](...data.args);
            port.postMessage({ id: data.id, result });
        } else {
            pending.get(data.id)(data.result);
            pending.delete(data.id);
        }
    };
    return (method, ...args) =>
        new Promise((resolve) => {
            const id = ++nextId;
            pending.set(id, resolve);
            port.postMessage({ id, method, args });
        });
}

const { port1, port2 } = new MessageChannel();
createRpc(port2, { add: (a, b) => a + b, greet: async (name) => `Salom, ${name}!` });
const call = createRpc(port1);

console.log(await call("add", 3, 4));
console.log(await call("greet", "Aziz"));
port1.close();

